import type {
  GitTransferProgress,
  HandwritingOcrListItem,
  NoteMeta,
  RecordingListItem,
} from "./types";
import { stripFrontmatter } from "./frontmatter";
import { stripInlineAnnotationMetadata } from "./annotation-metadata";

