21	const hasEnoughSlugContent = (value: string) =>
22	  slugContentCharCount(value) >= MIN_SLUG_CONTENT_CHARS;
23	
24	const isProvisionalSuffix = (suffix: string) =>
25	  !suffix || PLACEHOLDER_SUFFIX_RE.test(suffix) || !hasEnoughSlugContent(suffix);
