27	const stripNoiseTokenSequences = (tokens: string[]) => {
28	  const cleaned: string[] = [];
29	  for (let i = 0; i < tokens.length; i += 1) {
30	    if (
31	      i + 3 < tokens.length &&
32	      tokens[i] === "nv" &&
33	      tokens[i + 1] === "empty" &&
34	      tokens[i + 2] === "line" &&
35	      tokens[i + 3] === "token"
36	    ) {
37	      i += 3;
38	      if (i + 1 < tokens.length && NOISE_HASH_RE.test(tokens[i + 1])) {
39	        i += 1;
40	      }
