92	    setActiveFeedGroup: state.setActiveFeedGroup,
93	    renamingFolder: state.renamingFolder,
94	    setRenamingFolder: state.setRenamingFolder,
95	    renameValue: state.renameValue,
96	    setRenameValue: state.setRenameValue,
97	  });
98	
99	  // A phone pushing over local sync changes the notes on disk behind the
100	  // frontend's back; the backend emits this event after each accepted push.
101	  const { refreshTree } = state;
102	  useEffect(() => {
103	    const unlisten = listen("local-sync-push-received", () => {
104	      console.log("[notes] local sync push received — refreshing tree");
105	      void refreshTree();
106	    });
107	    return () => {
108	      void unlisten.then((dispose) => dispose());
109	    };
110	  }, [refreshTree]);
111	
112	  return (
113	    <NotesTreeContext.Provider value={{ ...state, ...actions }}>
114	      {children}
115	    </NotesTreeContext.Provider>
116	  );
117	}
118	
119	export function useNotesTree() {
120	  const context = useContext(NotesTreeContext);
121	  if (!context) {
122	    throw new Error("useNotesTree must be used within a NotesTreeProvider");
123	  }
124	  return context;
125	}

